        internal static byte[] Read()
        {
            var bytes=Convert.FromBase64String(Base64);
            using(var sha=SHA256.Create()) {
                string actual=string.Concat(sha.ComputeHash(bytes).Select(x=>x.ToString("x2",CultureInfo.InvariantCulture)));
                if(actual!=Sha256)throw new InvalidDataException("The pinned historical schema70 save fixture changed.");
            }
            return bytes;
        }
    }
